mapper.select:
SELECT t.*, req.nickname AS requester_name, prov.nickname AS provider_name FROM tasks t LEFT JOIN user_profiles req ON req.user_id = t.requester_id LEFT JOIN user_profiles prov ON prov.user_id = t.provider_id
AND t.status NOT IN ('DRAFT', 'PENDING_REVIEW', 'REJECTED')
AND (t.title LIKE CONCAT('%', #{query.keyword}, '%') OR t.description LIKE CONCAT('%', #{query.keyword}, '%'))
AND t.category = #{query.category}
AND t.campus = #{query.campus}
AND t.status = #{query.status}
AND t.status NOT IN ('DISPUTED', 'CANCELLED')
AND t.reward_type = #{query.rewardType}
AND t.requires_proof = #{query.requiresProof}
AND t.deadline > NOW()
ORDER BY t.deadline ASC
ORDER BY t.deadline DESC
ORDER BY t.created_at DESC
ORDER BY t.created_at DESC

SELECT * FROM tasks t
WHERE t.status = 'OPEN' AND t.deadline <= #{referenceTime}
  AND NOT EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.event_type = #{reminderEventType}
      AND h.created_at >= t.updated_at
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks t
WHERE t.status = 'PENDING_CONFIRMATION' AND t.updated_at <= #{referenceTime}
  AND NOT EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.event_type = #{reminderEventType}
      AND h.created_at >= t.updated_at
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks t
WHERE t.status = #{status}
  AND EXISTS (
    SELECT 1 FROM task_histories h
    WHERE h.task_id = t.id
      AND h.event_type = #{reminderEventType}
      AND h.created_at >= t.updated_at
      AND h.created_at <= #{reminderCreatedBefore}
  )
ORDER BY t.updated_at ASC, t.id ASC
LIMIT #{limit}

SELECT * FROM tasks
WHERE status = #{status}
  AND deadline > NOW()
ORDER BY created_at DESC
LIMIT #{size}

SELECT campus
FROM (
  SELECT requester_id AS user_id, campus FROM tasks WHERE campus IS NOT NULL
  UNION ALL
  SELECT provider_id AS user_id, campus FROM tasks WHERE provider_id IS NOT NULL AND campus IS NOT NULL
) combined
WHERE user_id = #{userId}
GROUP BY campus
ORDER BY COUNT(*) DESC
LIMIT #{limit}
